static const size_t k_tld_table_len = 1508;

static int ascii_icmp_n(const char *a, size_t alen,
                        const char *b, size_t blen)
{
    size_t n = (alen < blen) ? alen : blen;
    for (size_t i = 0; i < n; ++i) {
        int ca = tolower((unsigned char)a[i]);
        int cb = tolower((unsigned char)b[i]);
        if (ca != cb) return ca - cb;
    }
    if (alen < blen) return -1;
    if (alen > blen) return 1;
    return 0;
}

bool mdit_linkifier_full_tld_lookup(const char *s, size_t n)
{
    if (s == NULL || n == 0 || n > 63) return false;
    /* Binary search the case-insensitive sorted table. */
    size_t lo = 0, hi = k_tld_table_len;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        const mdit_tld_record *r = &k_tld_table[mid];
        const char *t = (const char *)k_tld_pool + r->off;
        int c = ascii_icmp_n(s, n, t, r->len);
        if (c == 0) return true;
        if (c < 0) hi = mid; else lo = mid + 1;
    }
    return false;
}

size_t mdit_linkifier_full_tld_count(void)
{
    return k_tld_table_len;
}
